package mezz.jei.common.config.legacy;

import net.mezzdev.config.api.schema.IConfigSchema;
import net.mezzdev.config.api.value.IConfigValue;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/** Imports the three booleans from JEI's old NeoForge TOML and Fabric properties files. */
public record LegacyServerConfigMigration(Path destination, Path source, Map<String, Boolean> values) {
	private static final Logger LOGGER = LogManager.getLogger();
	private static final Set<String> VALUE_NAMES = Set.of(
		"enableCheatModeForOp", "enableCheatModeForCreative", "enableCheatModeForGive"
	);

	public LegacyServerConfigMigration {
		destination = destination.toAbsolutePath().normalize();
		values = Map.copyOf(values);
	}

	public static Optional<LegacyServerConfigMigration> prepare(Path destination, List<Path> legacyPaths) {
		if (Files.exists(destination)) {
			return Optional.empty();
		}
		for (Path legacyPath : legacyPaths) {
			if (Files.exists(legacyPath)) {
				try {
					return Optional.of(new LegacyServerConfigMigration(destination, legacyPath, read(legacyPath)));
				} catch (IOException e) {
					throw new UncheckedIOException("Failed to read legacy JEI server config: " + legacyPath, e);
				}
			}
		}
		return Optional.empty();
	}

	private static Map<String, Boolean> read(Path path) throws IOException {
		Map<String, Boolean> values = new LinkedHashMap<>();
		boolean inCheatMode = path.getFileName().toString().endsWith(".properties");
		for (String line : Files.readAllLines(path)) {
			int comment = line.indexOf('#');
			if (comment >= 0) {
				line = line.substring(0, comment);
			}
			line = line.trim();
			if (line.startsWith("[")) {
				inCheatMode = line.endsWith("]") &&
					unquote(line.substring(1, line.length() - 1).trim()).equals("cheat mode");
				continue;
			}
			int separator = line.indexOf('=');
			if (!inCheatMode || separator < 0) {
				continue;
			}
			String name = unquote(line.substring(0, separator).trim());
			if (!VALUE_NAMES.contains(name)) {
				continue;
			}
			String value = line.substring(separator + 1).trim();
			if (value.equalsIgnoreCase("true") || value.equalsIgnoreCase("false")) {
				values.put(name, Boolean.parseBoolean(value));
			} else {
				LOGGER.warn("Ignoring invalid legacy JEI server config value '{} = {}' in '{}'", name, value, path);
			}
		}
		return values;
	}

	private static String unquote(String name) {
		if (name.length() >= 2 &&
			((name.startsWith("\"") && name.endsWith("\"")) || (name.startsWith("'") && name.endsWith("'")))
		) {
			return name.substring(1, name.length() - 1);
		}
		return name;
	}

	public void apply(IConfigSchema schema, List<IConfigValue<Boolean>> configValues) {
		Path activePath = schema.getPath().orElseThrow(() -> new IllegalStateException("JEI server config is not active"));
		if (!destination.equals(activePath.toAbsolutePath().normalize())) {
			throw new IllegalStateException("JEI server config migration belongs to another world: " + destination);
		}
		schema.batchUpdate(updater -> {
			for (IConfigValue<Boolean> configValue : configValues) {
				Boolean value = values.get(configValue.getEditorInfo().getName());
				if (value != null) {
					updater.set(configValue, value);
				}
			}
		});
		LOGGER.info("Imported legacy JEI server config from '{}' into '{}'. The original file was preserved.", source, destination);
	}
}

package mezz.jei.common.config;

import mezz.jei.api.constants.ModIds;
import mezz.jei.common.config.legacy.LegacyServerConfigMigration;
import net.mezzdev.config.api.Configs;
import net.mezzdev.config.api.schema.IConfigSchema;
import net.mezzdev.config.api.schema.builder.IConfigCategoryBuilder;
import net.mezzdev.config.api.schema.builder.IConfigSchemaBuilder;
import net.mezzdev.config.api.value.IConfigValue;

import java.nio.file.Path;
import java.util.List;
import java.util.Optional;

public final class ServerConfig implements IServerConfig {
	private static final String FILE_NAME = "jei-server.ini";

	private final IConfigValue<Boolean> enableCheatModeForOp;
	private final IConfigValue<Boolean> enableCheatModeForCreative;
	private final IConfigValue<Boolean> enableCheatModeForGive;
	private final IConfigSchema schema;
	private Optional<LegacyServerConfigMigration> pendingMigration = Optional.empty();

	public static ServerConfig register() {
		IConfigSchemaBuilder builder = Configs.forMod(ModIds.JEI_ID)
			.createServerSchemaBuilder(FILE_NAME, "jei.config.server");
		return new ServerConfig(builder);
	}

	private ServerConfig(IConfigSchemaBuilder builder) {
		IConfigCategoryBuilder permissions = builder.addCategory("permissions");
		enableCheatModeForOp = permissions.addBoolean("enableCheatModeForOp", true).build();
		enableCheatModeForCreative = permissions.addBoolean("enableCheatModeForCreative", true).build();
		enableCheatModeForGive = permissions.addBoolean("enableCheatModeForGive", false).build();
		schema = builder.build();
	}

	/**
	 * Check for legacy settings before MezzConfig creates the world's config file.
	 * MezzConfig's fixed legacy paths cannot follow successive singleplayer worlds.
	 */
	public void prepareLegacyMigration(Path worldConfigDirectory, List<Path> legacyPaths) {
		Path destination = worldConfigDirectory.resolve(ModIds.JEI_ID).resolve(FILE_NAME);
		pendingMigration = LegacyServerConfigMigration.prepare(destination, legacyPaths);
	}

	/** Apply the import after MezzConfig activates the world, before players join. */
	public void migrateLegacyConfig() {
		pendingMigration.ifPresent(migration -> migration.apply(
			schema,
			List.of(enableCheatModeForOp, enableCheatModeForCreative, enableCheatModeForGive)
		));
		pendingMigration = Optional.empty();
	}

	@Override
	public boolean isCheatModeEnabledForOp() {
		return enableCheatModeForOp.get();
	}

	@Override
	public boolean isCheatModeEnabledForCreative() {
		return enableCheatModeForCreative.get();
	}

	@Override
	public boolean isCheatModeEnabledForGive() {
		return enableCheatModeForGive.get();
	}
}

package mezz.jei.neoforge.config;

import mezz.jei.common.config.IServerConfig;
import mezz.jei.neoforge.events.PermanentEventSubscriptions;
import net.minecraft.world.level.storage.LevelResource;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.fml.loading.FMLPaths;
import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;
import net.neoforged.neoforge.event.server.ServerStartedEvent;

import java.nio.file.Path;
import java.util.List;

public final class ServerConfig {
	private ServerConfig() {}

	public static IServerConfig register(PermanentEventSubscriptions subscriptions) {
		var config = mezz.jei.common.config.ServerConfig.register();
		subscriptions.register(ServerAboutToStartEvent.class, event -> {
			Path worldConfigDirectory = event.getServer().getWorldPath(LevelResource.ROOT).resolve("serverconfig");
			config.prepareLegacyMigration(worldConfigDirectory, List.of(
				worldConfigDirectory.resolve("jei-server.toml"),
				FMLPaths.GAMEDIR.get().resolve("defaultconfigs").resolve("jei-server.toml")
			));
		});
		subscriptions.register(EventPriority.LOWEST, ServerStartedEvent.class, event -> config.migrateLegacyConfig());
		return config;
	}
}

package mezz.jei.fabric.config;

import mezz.jei.api.constants.ModIds;
import mezz.jei.common.config.IServerConfig;
import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;
import net.fabricmc.loader.api.FabricLoader;
import net.minecraft.resources.Identifier;
import net.minecraft.world.level.storage.LevelResource;

import java.nio.file.Path;
import java.util.List;

public final class ServerConfig {
	private ServerConfig() {}

	public static IServerConfig register() {
		var config = mezz.jei.common.config.ServerConfig.register();
		Path legacyConfig = FabricLoader.getInstance().getConfigDir().resolve("jei-server.properties");
		ServerLifecycleEvents.SERVER_STARTING.register(server -> {
			Path worldConfigDirectory = server.getWorldPath(LevelResource.ROOT).resolve("serverconfig");
			config.prepareLegacyMigration(worldConfigDirectory, List.of(legacyConfig));
		});
		Identifier migrationPhase = Identifier.fromNamespaceAndPath(ModIds.JEI_ID, "migrate_server_config");
		ServerLifecycleEvents.SERVER_STARTED.addPhaseOrdering(Event.DEFAULT_PHASE, migrationPhase);
		ServerLifecycleEvents.SERVER_STARTED.register(migrationPhase, server -> config.migrateLegacyConfig());
		return config;
	}
}

package mezz.jei.common.config.legacy;

import net.mezzdev.config.api.value.serializer.IDeserializeResult;
import net.mezzdev.config.api.value.serializer.IConfigValueSerializer;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class LegacyConfigValueLoader {
	private static final Pattern CATEGORY_PATTERN = Pattern.compile("\\s*\\[(?<category>\\w+)]\\s*");
	private static final Pattern VALUE_PATTERN = Pattern.compile("\\s*(?<key>\\w+)\\s*=\\s*(?<value>.*)");

	private LegacyConfigValueLoader() {}

	public static <T> IDeserializeResult<T> loadValue(
		Path path,
		String targetCategoryName,
		String targetValueName,
		IConfigValueSerializer<T> serializer
	) throws IOException {
		path = Objects.requireNonNull(path).toAbsolutePath().normalize();
		Objects.requireNonNull(targetCategoryName);
		Objects.requireNonNull(targetValueName);
		Objects.requireNonNull(serializer);
		return parseValue(path, Files.readAllLines(path), targetCategoryName, targetValueName, serializer);
	}

	private static <T> IDeserializeResult<T> parseValue(
		Path path,
		List<String> lines,
		String targetCategoryName,
		String targetValueName,
		IConfigValueSerializer<T> serializer
	) {
		String categoryName = "";
		String serializedValue = null;
		for (String line : lines) {
			Matcher categoryMatcher = CATEGORY_PATTERN.matcher(line);
			if (categoryMatcher.matches()) {
				categoryName = categoryMatcher.group("category");
				continue;
			}
			if (!targetCategoryName.equals(categoryName)) {
				continue;
			}
			Matcher valueMatcher = VALUE_PATTERN.matcher(line);
			if (valueMatcher.matches() && targetValueName.equals(valueMatcher.group("key"))) {
				serializedValue = valueMatcher.group("value").trim();
			}
		}

		if (serializedValue == null) {
			return IDeserializeResult.failure(
				"Legacy JEI config '%s' has no %s.%s value.".formatted(path, targetCategoryName, targetValueName)
			);
		}

		return serializer.deserialize(serializedValue);
	}
}

package mezz.jei.common.config.legacy;

import net.mezzdev.config.api.migration.IConfigMigrationContext;
import net.mezzdev.config.api.migration.IConfigMigrationResult;
import net.mezzdev.config.api.migration.IConfigMigrator;
import net.mezzdev.config.api.schema.builder.IConfigSchemaBuilder;
import net.mezzdev.config.api.value.IConfigValue;
import net.mezzdev.config.api.value.serializer.IDeserializeResult;
import net.mezzdev.config.api.value.serializer.IConfigValueSerializer;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.io.IOException;
import java.nio.file.Path;
import java.util.List;

/**
 * Loads a value written by JEI's config system and applies it through MezzConfig.
 * MezzConfig remains responsible for validating and saving its own file format.
 */
public final class LegacyConfigValueMigrator {
	private static final Logger LOGGER = LogManager.getLogger();

	private LegacyConfigValueMigrator() {}

	public static <T> void register(
		IConfigSchemaBuilder schema,
		List<Path> legacyPaths,
		IConfigValue<T> configValue,
		String categoryName,
		String valueName,
		IConfigValueSerializer<T> serializer
	) {
		if (!legacyPaths.isEmpty()) {
			schema.setLegacyMigration(
				legacyPaths,
				new ValueMigrator<>(configValue, categoryName, valueName, serializer)
			);
		}
	}

	private record ValueMigrator<T>(
		IConfigValue<T> configValue,
		String categoryName,
		String valueName,
		IConfigValueSerializer<T> serializer
	) implements IConfigMigrator {
		@Override
		public void migrate(Path path, IConfigMigrationContext context) throws IOException {
			IDeserializeResult<T> result = LegacyConfigValueLoader.loadValue(path, categoryName, valueName, serializer);
			result.getResult().ifPresent(value -> context.set(configValue, value));

			List<String> diagnostics = result.getDiagnostics();
			if (!diagnostics.isEmpty()) {
				context.rejectValue(
					"Failed to fully migrate legacy JEI config value '%s.%s' from '%s': %s"
						.formatted(categoryName, valueName, path, String.join("; ", diagnostics))
				);
			}
		}

		@Override
		public void onMigrationComplete(IConfigMigrationResult result) {
			if (result.getRejectedValueCount() > 0) {
				LOGGER.warn(
					"Legacy JEI config migration imported {} value(s) and rejected {} value(s): {}",
					result.getImportedValueCount(),
					result.getRejectedValueCount(),
					String.join("; ", result.getDiagnostics())
				);
			}
		}
	}
}

package mezz.jei.common.config.legacy;

import java.nio.file.Path;
import java.util.List;
import java.util.Objects;
import java.util.UUID;

import org.jspecify.annotations.Nullable;

public final class LegacyConfigPaths {
	private LegacyConfigPaths() {}

	public static List<Path> get(Path jeiConfigDirectory, @Nullable UUID profileId, String fileName) {
		jeiConfigDirectory = Objects.requireNonNull(jeiConfigDirectory).toAbsolutePath().normalize();
		Objects.requireNonNull(fileName);

		Path legacyFile = jeiConfigDirectory.resolve(fileName);
		if (profileId == null) {
			return List.of(legacyFile);
		}

		Path legacyProfileFile = jeiConfigDirectory.resolve("players").resolve(profileId.toString()).resolve(fileName);
		return List.of(legacyProfileFile, legacyFile);
	}
}
